import 'dart:ui';

/// SVG 路径（仅 M/L/Z）转成 even-odd [Path]。坐标在 0–100 设计框里。
Path modeIconPath(String d) {
  final path = Path()..fillType = PathFillType.evenOdd;
  final tokens = RegExp(r'[MLZ]|-?\d*\.?\d+').allMatches(d).map((m) => m.group(0)!).toList();
  var i = 0;
  String? cmd;
  while (i < tokens.length) {
    final t = tokens[i];
    if (t == 'M' || t == 'L' || t == 'Z') {
      cmd = t;
      i++;
      if (cmd == 'Z') path.close();
      continue;
    }
    final x = double.parse(t);
    final y = double.parse(tokens[++i]);
    i++;
    if (cmd == 'M') {
      path.moveTo(x, y);
      cmd = 'L';
    } else if (cmd == 'L') {
      path.lineTo(x, y);
    }
  }
  return path;
}

